def read_api_keys(file_path):
    with open(file_path, 'r') as file:
        api_keys = [line.strip() for line in file.readlines() if line.strip()]
    return api_keys

def generate_token(api_key, resource):
    combined = f"{SECRET}{api_key}{resource}"
    return hashlib.sha256(combined.encode()).hexdigest()

def validate_token(token, resource):
    combined = f"{SECRET}{token}"
    hash_obj = hashlib.sha256(combined.encode())
    recovered_token = hash_obj.hexdigest()
    if token != recovered_token:
        return None

    # Extract resource and expiration from token (assuming token is formatted as <resource>_<expiration>)
